                                                                            "script": {
                                                                                "apiVersion": "2.0.0",
                                                                                "controllerElementId": null,
                                                                                "inlineScript": "/**\n  * @param {params} params\n  * @param {api} params.api\n  * @param {TransformApiHelpers} params.helpers\n  */\nfunction evaluateProperty({api, helpers}) {\n  var items = api.data.record_form.actions.items;\n  var primaryItems = [];\n  /** \n   * Update the below number to change the position \n   * of primary action on the playbook form.\n   */\n  var numberOfActions = api.state.numberOfActions;\n  var newItems = [];\n  \n  if(items==undefined || items.length==0)\n    return '';\n    \n  for(var i=0; i<items.length;i++){\n    if(items[i]['color']=='primary'){\n      primaryItems.push(items[i]);\n    }\n    else if(items[i]['children'][0]['label']!=='Discuss'){\n            newItems.push(items[i]);\n    }\n  }\n  if(newItems.length < numberOfActions){\n    newItems.push(...primaryItems);\n    return newItems;\n  }\n  return [...newItems.slice(0, numberOfActions-1), ...primaryItems, ...newItems.slice(numberOfActions-1)];\n}\n",
                                                                                "scriptSysId": "9d4332d3a336311010557a2a241e6112",
                                                                                "target": null
