            "conditional": null,
            "declarativeAction": null,
            "event": {
                "apiName": "sn_uxf.MACROPONENT_STATE_UPDATE_REQUESTED",
                "payload": {
                    "script": {
                        "apiVersion": "1.0.0",
                        "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.event\n * @param {any} params.imports\n */\nfunction evaluateEvent({\n    api,\n    event\n}) {\n    const propName = \"refreshRequested\";\n    if (event.payload.name === \"advanced\") {\n        const { associatedRecordModCount = 0 } = event.payload.value;\n        const { associatedRecordModCount: prevModCount = 0 } = event.payload.previousValue;\n\n        if (associatedRecordModCount > prevModCount) {\n            return {\n                propName,\n                value: { timestamp: Date.now(), background: false }\n            };\n        }\n    }\n\n    return {\n        propName,\n        value: {}\n    };\n}",
                        "scriptSysId": null
                    },
                    "type": "CLIENT_TRANSFORM_SCRIPT"
                },
                "sysId": "32408b42ff7a10109046e490703bf176"
            },
            "operation": null,
            "targetId": "cksumiixooaaaaddsddhhhsfqxjjhhyebb",
            "type": "EVENT"
