                        "inlineScript": "/**\n* @param {params} params\n* @param {api} params.api\n* @param {any} params.event\n* @param {any} params.imports\n*/\nfunction evaluateEvent({api, event}) {\n\t// INSERT ANY CUSTOM SUFFICIENT DATA LOGIC HERE\n\n\tconst { experienceProperties } = api.context.props;\n\n\tconst {\n\t\tlist_title = {},\n\t\ttable = {}\n\t} = experienceProperties;\n\n\tconst propName = 'hasSufficientData';\n\t\n\t// list card requires list table and list title\n\treturn {\n\t\tpropName,\n\t\tvalue: list_title.value && table.value\n\t};\n}",
